import{_ as l,a0 as m,w as d,s as i,ao as a,I as o,x as t,a1 as p,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"RHCSA 系列（九）: Yum 包管理、Cron 自動任務計劃和監控系統日誌 | LCTT x X-CMD","titleTemplate":false,"description":"RHCSA 系列（九）: Yum 包管理、Cron 自動任務計劃和監控系統日誌 | LCTT (RHCSA Series) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"RHCSA 系列（九）: Yum 包管理、Cron 自動任務計劃和監控系統日誌 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"RHCSA 系列（九）: Yum 包管理、Cron 自動任務計劃和監控系統日誌 | LCTT (RHCSA Series) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RHCSA Series/RHCSA Series--Part 10--Yum Package Management, Automating Tasks with Cron and Monitoring System Logs","title":"RHCSA 系列（九）: Yum 包管理、Cron 自動任務計劃和監控系統日誌","tag":"RHCSA Series","desc":""},"relativePath":"RHCSA Series/RHCSA Series--Part 10--Yum Package Management, Automating Tasks with Cron and Monitoring System Logs.md","filePath":"[post].md"}'),s={name:"RHCSA Series/RHCSA Series--Part 10--Yum Package Management, Automating Tasks with Cron and Monitoring System Logs.md"};function c(u,e,g,w,C,y){const n=m("Link");return d(),i("div",null,[e[22]||(e[22]=a(`<h1 id="rhcsa-系列-九-yum-包管理、cron-自動任務計劃和監控系統日誌" tabindex="-1">RHCSA 系列（九）: Yum 包管理、Cron 自動任務計劃和監控系統日誌 <a class="header-anchor" href="#rhcsa-系列-九-yum-包管理、cron-自動任務計劃和監控系統日誌" aria-label="Permalink to “RHCSA 系列（九）: Yum 包管理、Cron 自動任務計劃和監控系統日誌”">​</a></h1><p>在這篇文章中，我們將回顧如何在 RHEL7 中安裝，更新和刪除軟件包。我們還將介紹如何使用 cron 進行任務自動化，並完成如何查找和監控系統日誌文件，以及為什麼這些技能是系統管理員必備技能。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Yum-Package-Management-Cron-Job-Log-Monitoring-Linux.jpg" alt="Yum Package Management Cron Jobs Log Monitoring Linux"></p><p><em>RHCSA: Yum包管理、任務計劃和系統監控 – Part 10</em></p><h3 id="使用yum-管理包" tabindex="-1">使用yum 管理包 <a class="header-anchor" href="#使用yum-管理包" aria-label="Permalink to “使用yum 管理包”">​</a></h3><p>要安裝一個包以及所有尚未安裝的依賴包，您可以使用：</p><pre><code># yum -y install package_name(s)
</code></pre><p>package_name(s) 需要是至少一個真實的軟件包名</p><p>例如，安裝 httpd 和 mlocate（按順序），輸入。</p><pre><code># yum -y install httpd mlocate
</code></pre><p><strong>注意</strong>: 字符 y 表示繞過執行下載和安裝前的確認提示。如果需要提示，你可以不用它。</p><p>默認情況下，yum 將安裝與操作系統體系結構相匹配的包，除非通過在包名加入架構名。</p><p>例如，在 64 位系統上，<code>yum install package</code>將安裝包的 x86_64 版本，而 <code>yum install package.x86</code>（如果有的話）將安裝 32 位的。</p><p>有時，你想安裝一個包，但不知道它的確切名稱。<code>search all</code> 選項可以在當前啓用的軟件庫中的包名稱和包描述中搜索它，或者<code>search</code>選項可以在包名稱中搜索。</p><p>比如，</p><pre><code># yum search log
</code></pre><p>將搜索安裝的軟件庫中名字和摘要與該詞（log）類似的軟件，而</p><pre><code># yum search all log
</code></pre><p>也將在包描述和網址中尋找尋找相同的關鍵字。</p><p>一旦搜索返回包列表，您可能希望在安裝前顯示一些信息。這時 info 選項派上了用場：</p><pre><code># yum info logwatch
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Search-Package-Information.png" alt="Search Package Information"></p><p><em>搜索包信息</em></p><p>您可以定期用以下命令檢查更新：</p><pre><code># yum check-update
</code></pre><p>上述命令將返回可以更新的所有已安裝的軟件包。在下圖所示的例子中，只有 rhel-7-server-rpms 有可用更新：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Check-For-Updates.png" alt="Check For Package Updates"></p><p><em>檢查包更新</em></p><p>然後，您可以更新該包，</p><pre><code># yum update rhel-7-server-rpms
</code></pre><p>如果有幾個包可以一同更新，可以使用 <code> yum update</code> 一次性更新所有的包。</p><p>當你知道一個可執行文件的名稱，如 ps2pdf，但不知道那個包提供了它？你可以通過 <code>yum whatprovides “*/[executable]”</code>找到:</p><pre><code># yum whatprovides “*/ps2pdf”
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Find-Package-Information.png" alt="Find Package Belongs to Which Package"></p><p><em>查找文件屬於哪個包</em></p><p>當刪除包時，你可以使用 <code>yum remove Package</code> ，很簡單吧？Yum 是一個完整而強大的包管理器。</p><pre><code># yum remove httpd
</code></pre>`,37)),o("ul",null,[o("li",null,[e[1]||(e[1]=t("參見： ",-1)),p(n,{href:"http://www.tecmint.com/20-linux-yum-yellowdog-updater-modified-commands-for-package-mangement/"},{default:r(()=>[...e[0]||(e[0]=[t("20 個管理 RHEL 7 軟件包的 Yum 命令",-1)])]),_:1})])]),e[23]||(e[23]=a(`<h3 id="文本式-rpm-工具" tabindex="-1">文本式 RPM 工具 <a class="header-anchor" href="#文本式-rpm-工具" aria-label="Permalink to “文本式 RPM 工具”">​</a></h3><p>RPM（又名 RPM 包管理器，原意是 RedHat 軟件包管理器）也可用於安裝或更新獨立的<code>rpm</code>格式的軟件包。</p><p>往往使用 <code>-Uvh</code> 表明如果這個包沒有安裝就安裝它，如果已存在就嘗試更新。這裏<code>-U</code>表示更新、<code>-v</code>表示顯示詳細輸出，用<code>-h</code>顯示進度條。例如</p><pre><code># rpm -Uvh package.rpm
</code></pre><p>rpm 的另一個典型的使用方法是列出所有安裝的軟件包，</p><pre><code># rpm -qa
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Query-All-RPM-Packages.png" alt="Query All RPM Packages"></p><p><em>查詢所有包</em></p>`,8)),o("ul",null,[o("li",null,[e[3]||(e[3]=t("參見： ",-1)),p(n,{href:"http://www.tecmint.com/20-practical-examples-of-rpm-commands-in-linux/"},{default:r(()=>[...e[2]||(e[2]=[t("20 個管理 RHEL 7 軟件包的 RPM 命令",-1)])]),_:1})])]),e[24]||(e[24]=a(`<h3 id="使用-cron-調度任務" tabindex="-1">使用 Cron 調度任務 <a class="header-anchor" href="#使用-cron-調度任務" aria-label="Permalink to “使用 Cron 調度任務”">​</a></h3><p>Linux 和 UNIX 類操作系統包括一個稱為 Cron 的工具，允許你週期性調度任務（即命令或 shell 腳本）。cron 會每分鐘定時檢查 /var/spool/cron 目錄中有在 /etc/passwd 帳户文件中指定用户名的文件。</p><p>執行命令時，命令輸出是發送到該 crontab 的所有者（或者可以在 /etc/crontab，通過 MAILTO 環境變量中指定用户）。</p><p>crontab 文件（可以通過鍵入 <code>crontab -e</code>並按 Enter 鍵創建）的格式如下：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Crontab-Format.png" alt="Crontab Entries"></p><p><em>crontab條目</em></p><p>因此，如果我們想在每個月第二天上午2:15更新本地文件資料庫（用於按名字或通配模式定位文件），我們需要添加以下 crontab 條目：</p><pre><code>15 02 2 * * /bin/updatedb
</code></pre><p>以上的條目的意思是：”每年每月第二天的凌晨 2：15 運行 /bin/updatedb，無論是周幾”，我想你也猜到了。星號作為通配符。</p><p>正如我們前面所提到的，添加一個 cron 任務後，你可以看到一個名為 root 的文件被添加在 /var/spool/cron。該文件列出了所有的 crond 守護進程應該運行的任務：</p><pre><code># ls -l /var/spool/cron
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Check-All-Cron-Jobs.png" alt="Check All Cron Jobs"></p><p><em>檢查所有cron任務</em></p><p>在上圖中，顯示當前用户的 crontab 可以使用 <code>cat /var/spool/cron</code> 或</p><pre><code># crontab -l
</code></pre><p>如果你需要在一個更精細的時間上運行的任務（例如，一天兩次或每月三次），cron 也可以做到。</p><p>例如，每個月1號和15號運行 /my/script 並將輸出導出到 /dev/null （丟棄輸出），您可以添加如下兩個crontab 條目：</p><pre><code>01 00 1 * * /myscript &gt; /dev/null 2&gt;&amp;1
01 00 15 * * /my/script &gt; /dev/null 2&gt;&amp;1
</code></pre><p>不過為了簡單，你可以將他們合併：</p><pre><code>01 00 1,15 * *  /my/script &gt; /dev/null 2&gt;&amp;1
</code></pre><p>跟着前面的例子，我們可以在每三個月的第一天的凌晨1：30運行 /my/other/script。</p><pre><code>30 01 1 1,4,7,10 * /my/other/script &gt; /dev/null 2&gt;&amp;1
</code></pre><p>但是當你必須每隔某分鐘、小時、天或月來重複某個任務時，你可以通過所需的頻率來劃分正確的時間。以下與前一個 crontab 條目具有相同的意義：</p><pre><code>30 01 1 */3 * /my/other/script &gt; /dev/null 2&gt;&amp;1
</code></pre><p>或者也許你需要在一個固定的頻率或系統啓動後運行某個固定的工作，你可以使用下列五個字符串中的一個字符串來指示你想讓你的任務計劃工作的確切時間：</p><pre><code>@reboot    	僅系統啓動時運行
@yearly    	一年一次, 類似與 00 00 1 1 *
@monthly   	一月一次, 類似與 00 00 1 * *
@weekly    	一週一次, 類似與 00 00 * * 0
@daily     	一天一次, 類似與 00 00 * * *
@hourly    	一小時一次, 類似與 00 * * * *
</code></pre>`,26)),o("ul",null,[o("li",null,[e[5]||(e[5]=t("參見：",-1)),p(n,{href:"http://www.tecmint.com/11-cron-scheduling-task-examples-in-linux/"},{default:r(()=>[...e[4]||(e[4]=[t("11 個在 RHEL7 中調度任務的命令",-1)])]),_:1})])]),e[25]||(e[25]=o("h3",{id:"定位和查看日誌",tabindex:"-1"},[t("定位和查看日誌### "),o("a",{class:"header-anchor",href:"#定位和查看日誌","aria-label":"Permalink to “定位和查看日誌###”"},"​")],-1)),e[26]||(e[26]=o("p",null,"系統日誌存放（並輪轉）在 /var/log 目錄。根據 Linux 的文件系統層次標準（Linux Filesystem Hierarchy Standard），這個目錄包括各種日誌文件，並包含一些必要的子目錄（如 audit、 httpd 或 samba ，如下圖)，並由相應的系統守護進程操作：",-1)),e[27]||(e[27]=o("pre",null,[o("code",null,`# ls /var/log
`)],-1)),e[28]||(e[28]=o("p",null,[o("img",{src:"http://www.tecmint.com/wp-content/uploads/2015/05/Linux-Log-Files.png",alt:"Linux Log Files Location"})],-1)),e[29]||(e[29]=o("p",null,[o("em",null,"Linux 日誌的位置")],-1)),o("p",null,[e[7]||(e[7]=t("其他感興趣的日誌比如 ",-1)),p(n,{href:"http://www.tecmint.com/dmesg-commands/"},{default:r(()=>[...e[6]||(e[6]=[t("dmesg",-1)])]),_:1}),e[8]||(e[8]=t("（包括了所有內核層緩衝區的消息），secure（記錄要求用户認證的連接請求)，messages（系統級信息），和 wtmp（記錄了所有用户的登錄、登出）。",-1))]),e[30]||(e[30]=a(`<p>日誌是非常重要的，它們讓你可以看到任何時刻發生在你的系統的事情，以及已經過去的事情。他們是無價的工具，可以排錯和監測一個 Linux 服務器，通常使用 <code>tail -f</code> 命令來實時顯示正在發生和寫入日誌的事件。</p><p>舉個例子，如果你想看你的內核相關的日誌，你需要輸入如下命令：</p><pre><code># tail -f /var/log/dmesg
</code></pre><p>同樣的，如果你想查看你的 Web 服務器日誌，你需要輸入如下命令：</p><pre><code># tail -f /var/log/httpd/access.log
</code></pre><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>如果你知道如何有效的管理包、調度任務、以及知道在哪尋找系統當前和過去操作的信息，你可以放鬆工作而不會總被嚇到。我希望這篇文章能夠幫你學習或回顧這些基礎知識。</p><p>如果你有任何問題或意見，請使用下面的表單反饋給我們。</p><hr>`,9)),o("p",null,[e[10]||(e[10]=t("via: ",-1)),p(n,{href:"http://www.tecmint.com/yum-package-management-cron-job-scheduling-monitoring-linux-logs/"},{default:r(()=>[...e[9]||(e[9]=[t("http://www.tecmint.com/yum-package-management-cron-job-scheduling-monitoring-linux-logs/",-1)])]),_:1})]),o("p",null,[e[14]||(e[14]=t("作者：",-1)),p(n,{href:"http://www.tecmint.com/author/gacanepa/"},{default:r(()=>[...e[11]||(e[11]=[t("Gabriel Cánepa",-1)])]),_:1}),e[15]||(e[15]=t(" 譯者：",-1)),p(n,{href:"https://github.com/xiqingongzi"},{default:r(()=>[...e[12]||(e[12]=[t("xiqingongzi",-1)])]),_:1}),e[16]||(e[16]=t(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:r(()=>[...e[13]||(e[13]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[19]||(e[19]=t("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[17]||(e[17]=[t("LCTT",-1)])]),_:1}),e[20]||(e[20]=t(" 原創翻譯，",-1)),p(n,{href:"https://linux.cn/"},{default:r(()=>[...e[18]||(e[18]=[t("Linux中國",-1)])]),_:1}),e[21]||(e[21]=t(" 榮譽推出",-1))])])}const T=l(s,[["render",c]]);export{f as __pageData,T as default};
